#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <cstring>
#define main original_fhd_main
#include "../fhd-cuda/main.cu"
#undef main
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
template<class T>std::vector<T>load(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);size_t n=f.tellg();f.seekg(0);std::vector<T>v(n/sizeof(T));f.read((char*)v.data(),n);return v;}
constexpr float SENT=-8192.25f;
struct Buf{float*d;std::vector<float>h;Buf(std::vector<float>v){h.assign(v.size()+8,SENT);std::copy(v.begin(),v.end(),h.begin()+4);ck(cudaMalloc(&d,h.size()*4));reset();}float*ptr(){return d+4;}void reset(){ck(cudaMemcpy(d,h.data(),h.size()*4,cudaMemcpyHostToDevice));}std::vector<float>get(){std::vector<float>r(h.size());ck(cudaMemcpy(r.data(),d,r.size()*4,cudaMemcpyDeviceToHost));return r;}};
struct Case{int ns,nv;Buf*r,*im,*ro,*io,*x,*y,*z;std::vector<kdata>host,expected;};
void run(Case&c){for(int base=0;base<c.nv;base+=4096){int n=std::min(4096,c.nv-base);ck(cudaMemcpyToSymbol(k,c.host.data()+base,n*sizeof(kdata)));cmpfhd<<<(c.ns+255)/256,256>>>(c.r->ptr()+base,c.im->ptr()+base,c.ro->ptr(),c.io->ptr(),c.x->ptr(),c.y->ptr(),c.z->ptr(),c.ns,n);}ck(cudaDeviceSynchronize());}
int main(){auto f=load<float>(FHD_FIXTURE);auto o=load<double>(FHD_ORACLE);std::vector<Case>cs;size_t i=0;while(i<f.size()){Case c;c.ns=f[i];c.nv=f[i+1];i+=3;auto take=[&](int n){std::vector<float>v(f.begin()+i,f.begin()+i+n);i+=n;return v;};c.r=new Buf(take(c.nv));c.im=new Buf(take(c.nv));c.host.resize(c.nv);memcpy(c.host.data(),f.data()+i,12*c.nv);i+=3*c.nv;c.ro=new Buf(take(c.ns));c.io=new Buf(take(c.ns));c.x=new Buf(take(c.ns));c.y=new Buf(take(c.ns));c.z=new Buf(take(c.ns));c.expected.resize(4096);for(int b=0;b<c.nv;b+=4096)std::copy(c.host.begin()+b,c.host.begin()+std::min(b+4096,c.nv),c.expected.begin());cs.push_back(c);}std::vector<kdata>zero(4096);auto reset=[&](Case&c){c.ro->reset();c.io->reset();ck(cudaMemcpyToSymbol(k,zero.data(),49152));ck(cudaDeviceSynchronize());};for(auto&c:cs){reset(c);run(c);}
 for(int trial=1;trial<=5;trial++){auto out=f;bool ok=true;double tm=0,err=0;size_t oi=0;for(auto&c:cs){reset(c);auto start=std::chrono::steady_clock::now();run(c);tm+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto ro=c.ro->get(),io=c.io->get();for(auto&v:{ro,io})for(int j=4;j<c.ns+4;j++){double e=fabs(double(v[j])-o[oi]);err=fmax(err,e);ok&=e<=1e-4+2e-5*fabs(o[oi++]);}int bidx=0;for(auto*b:{c.r,c.im,c.ro,c.io,c.x,c.y,c.z}){auto h=b->get();if(bidx==0||bidx==1||bidx>=4)ok&=memcmp(h.data(),b->h.data(),h.size()*4)==0;for(int j=0;j<4;j++)ok&=h[j]==SENT;for(size_t j=h.size()-4;j<h.size();j++)ok&=h[j]==SENT;out.insert(out.end(),h.begin(),h.end());bidx++;}std::vector<kdata>actual(4096);ck(cudaMemcpyFromSymbol(actual.data(),k,49152));ok&=memcmp(actual.data(),c.expected.data(),49152)==0;float*raw=(float*)actual.data();out.insert(out.end(),raw,raw+12288);}std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream z(path,std::ios::binary);z.write((char*)out.data(),out.size()*4);z.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"timing_region\":\"sum3_constant_chunk_upload_and_Fourier_kernel_pipeline_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,tm,ok?"true":"false",out.size(),err,path.c_str(),out.size());if(!ok)return 3;}}
